	now := time.Date(2026, 9, 13, 12, 0, 0, 0, time.UTC)
	opts, storage := newPrepassBackoffBrain(t, now)
	if out, err := execute(t, newMemoryWorkerCommand(opts), "--once"); err != nil {
		t.Fatalf("worker: %v\n%s", err, out)
	}

	state, err := loadMemoryCoordinatorState(storage.BrainDir)
	if err != nil {
		t.Fatalf("coordinator state: %v", err)
	}
	if state.LastOutcome != memoryWorkerOutcomeDegraded {
		t.Fatalf("last_outcome = %q, want %q", state.LastOutcome, memoryWorkerOutcomeDegraded)
	}

	health := memoryReadOnlyHealth(storage.BrainDir, now.Add(time.Second))
	coordinator, ok := health.Payload["coordinator"].(map[string]any)
	if !ok {
		t.Fatalf("no coordinator health section: %+v", health.Payload)
	}
	if code, _ := coordinator["error_code"].(string); code != memoryErrWorkerDegraded {
		t.Fatalf("coordinator health hides the degraded pass: %+v", coordinator)
	}
	found := false
	for _, issue := range health.Issues {
		if issue.Code == memoryErrWorkerDegraded {
			found = true
		}
	}
	if !found {
		t.Fatalf("a degraded worker pass raised no status issue: %+v", health.Issues)
	}
}

// A successful prepass ends the chain: the next pass starts from zero.
func TestSuccessfulPrepassResetsTheRelaunchChain(t *testing.T) {
	oldPrepass, oldLaunchAfter := memoryWorkerPrepass, memoryWorkerLaunchAfter
	defer func() { memoryWorkerPrepass, memoryWorkerLaunchAfter = oldPrepass, oldLaunchAfter }()
	if err := writeBrainManifestAndReadme(storage.BrainDir, exportManifest{SchemaVersion: brainManifestSchemaVersion, RepoKey: storage.Key}); err != nil {
		t.Fatal(err)
	}
	pending := memoryJob{Kind: memoryJobKindProjection, RepoKey: storage.Key, SessionID: "already-exported", SessionRef: "conversation-session:already-exported", InputDigest: "sha256:already-exported", Trigger: "startup", State: memoryJobStatePending, CreatedAt: now, AvailableAt: now}
	pending.JobID = memoryJobID(pending.RepoKey, pending.SessionRef, pending.InputDigest, pending.Kind)
	if err := saveMemoryJob(storage.BrainDir, pending); err != nil {
		t.Fatal(err)
	}
	oldPrepass, oldLaunchAfter := memoryWorkerPrepass, memoryWorkerLaunchAfter
	defer func() { memoryWorkerPrepass, memoryWorkerLaunchAfter = oldPrepass, oldLaunchAfter }()
	prepassCalls := 0
	memoryWorkerPrepass = func(context.Context, Options, string) error {
		prepassCalls++
		return errors.New("temporary export failure")
	}
	var scheduled time.Duration
	scheduledFailures := -1
	memoryWorkerLaunchAfter = func(_ string, delay time.Duration, failures int) error {
		scheduled, scheduledFailures = delay, failures
		return nil
	}
	out, err := execute(t, newMemoryWorkerCommand(opts), "--once")
	if err != nil {
		t.Fatalf("worker must continue already-exported work after prepass failure: %v\n%s", err, out)
	}
	// The first failure in a chain still retries in a minute; the chain now
	// carries its failure count so the next one backs off instead of repeating.
	if prepassCalls != 1 || scheduled != time.Minute || scheduledFailures != 1 ||
		!strings.Contains(out, `"prepass_failed": true`) || !strings.Contains(out, `"jobs_retried": 1`) {
		t.Fatalf("prepass calls=%d scheduled=%v failures=%d output=%s", prepassCalls, scheduled, scheduledFailures, out)
	}
	job, err := memoryJobByID(storage.BrainDir, pending.JobID)
	if err != nil || job.State != memoryJobStateRetryable {
		t.Fatalf("already-exported pending work did not continue: job=%+v err=%v", job, err)
	}
}

