			continue
		}
		key := distillSessionCacheKeyFor(branch, session, duplicateKeys)
		if prev, ok := prevCache.Sessions[key]; ok {
			newCache.Sessions[key] = prev
		} else if prev, ok := prevCache.Sessions[session.SessionID]; ok {
