func TestLongDelayedWorkerDoesNotHoldTheCoordinatorWhileWaiting(t *testing.T) {
	oldCap := memoryWorkerMaxLeaseSleep
	defer func() { memoryWorkerMaxLeaseSleep = oldCap }()
	memoryWorkerMaxLeaseSleep = 50 * time.Millisecond

